  v_tag text := '[VEDU-KTLT-LESSON-10Q-V2] 10 câu biên soạn theo chủ đề Kỹ thuật lập trình C++';
  v_data jsonb := $quizdata$[{"order":1,"questions":[{"text":"Trong C++, RAII giúp quản lý tài nguyên theo cách nào?","options":["Giải phóng tài nguyên chỉ khi gọi delete thủ công","Giữ tài nguyên đến khi chương trình thoát","Giải phóng tài nguyên khi đối tượng ra khỏi phạm vi","Chuyển mọi tài nguyên sang bộ nhớ tĩnh"],"answer":3},{"text":"Khối catch(const std::exception& e) thường dùng để làm gì?","options":["Bắt duy nhất lỗi chia cho số 0","Tạo ngoại lệ mới khi chương trình chạy đúng","Bắt ngoại lệ thuộc hệ phân cấp std::exception","Bắt mọi lỗi cú pháp trước khi biên dịch"],"answer":3},{"text":"Lệnh mở tập tin để ghi và thay thế nội dung cũ bằng std::ofstream thường là gì?","options":["std::fstream f(\"out.txt\", std::ios::in);","std::ofstream f(\"out.txt\");","std::ifstream f(\"out.txt\", std::ios::app);","std::ifstream f(\"out.txt\");"],"answer":2},{"text":"Sau khi mở std::ifstream f(\"data.txt\"), cách nào kiểm tra mở tệp thành công?","options":["Kiểm tra f.is_open()","Kiểm tra f.gcount() bằng 1","Kiểm tra f.eof() ngay trước khi đọc","Kiểm tra f.tellg() luôn bằng -1"],"answer":1},{"text":"Trong C++, std::getline(f, line) khác toán tử f >> line ở điểm nào?","options":["Chỉ đọc ký tự đầu của mỗi dòng","Tự bỏ mọi ký tự khoảng trắng trong dòng","Đọc cả dòng và giữ khoảng trắng ở giữa","Tự chuyển dòng thành số nguyên"],"answer":3},{"text":"Thành phần nào chạy tự động khi đối tượng C++ thông thường ra khỏi phạm vi?","options":["Hàm tạo sao chép (copy constructor)","Hàm main()","Hàm hủy (destructor)","Hàm nạp chồng toán tử <<"],"answer":3},{"text":"Trong xử lý ngoại lệ C++, từ khóa nào dùng để phát sinh ngoại lệ?","options":["retry","catch","finally","throw"],"answer":4},{"text":"Khi đọc file số nguyên có dữ liệu hỏng giữa chừng, biểu thức if (!(f >> x)) giúp phát hiện điều gì?","options":["Tệp có quyền ghi","Phép đọc không thành công","Biến x đã được cấp phát động","Chương trình đã thoát mọi vòng lặp"],"answer":2},{"text":"Khi tổ chức một chương trình xử lý tập tin, cách chia hàm nào dễ kiểm thử nhất?","options":["Tách đọc dữ liệu, xử lý và ghi kết quả","Đặt mọi thao tác trong hàm main dài duy nhất","Ghi dữ liệu ngay trong mỗi phép cộng","Dùng biến toàn cục cho mọi dữ liệu"],"answer":1},{"text":"Nếu std::ofstream không mở được tệp đầu ra, chương trình nên làm gì?","options":["Tiếp tục và báo đã lưu file","Gọi close() nhiều lần đến khi có file","Thông báo lỗi và không giả định ghi thành công","Đọc lại file bằng toán tử >>"],"answer":3}]},{"order":2,"questions":[{"text":"Với mảng int a[5], chỉ số hợp lệ trong C++ là tập nào?","options":["0 đến 4","0 đến 5","-1 đến 3","1 đến 5"],"answer":1},{"text":"Để tính tổng n phần tử mảng với n>0, độ phức tạp thời gian thông thường là?","options":["O(n²)","O(n)","O(log n)","O(1)"],"answer":2},{"text":"Khi tìm phần tử lớn nhất trong mảng không rỗng, nên khởi tạo maxValue thế nào?","options":["maxValue = 0 cho mọi mảng","maxValue = n","maxValue = a[n]","maxValue = a[0]"],"answer":4},{"text":"Mảng {3, 8, 3, 1} có bao nhiêu phần tử chẵn?","options":["1","3","2","0"],"answer":1},{"text":"Tìm kiếm tuyến tính trong mảng n phần tử có độ phức tạp xấu nhất là?","options":["O(n log n)","O(n)","O(1)","O(log n)"],"answer":2},{"text":"Nếu a = {2, 5, 7, 9}, a[2] có giá trị bao nhiêu?","options":["9","5","7","2"],"answer":3},{"text":"Đoạn mã C++ nào đếm đúng số phần tử chẵn trong mảng a độ dài n?","options":["if (a[i] / 2 == 0) count++;","if (a[i] % 2 == 0) count++;","if (a[i] % 2 == 1) count++;","if (i % 2 == 0) count++;"],"answer":2},{"text":"Khi n = 1, giá trị nhỏ nhất và lớn nhất của mảng một phần tử có quan hệ thế nào?","options":["Bằng nhau","Nhỏ nhất luôn bằng 0","Lớn nhất luôn bằng 1","Không xác định dù phần tử hợp lệ"],"answer":1},{"text":"Khi tìm vị trí xuất hiện đầu tiên của x bằng duyệt từ trái sang phải, nên làm gì ngay khi thấy x?","options":["Đổi x thành 0","Lưu chỉ số và dừng vòng lặp","Tiếp tục để lưu lần xuất hiện cuối","Sắp xếp lại mảng trước khi trả chỉ số"],"answer":2},{"text":"Trước khi đọc vào int a[1000] với n nhập từ bàn phím, điều kiện kiểm tra quan trọng là?","options":["n > 1000","n == 0","1 <= n && n <= 1000","n < 0"],"answer":3}]},{"order":3,"questions":[{"text":"Chèn phần tử vào vị trí k của mảng đã có n phần tử cần làm gì để không ghi đè?","options":["Chỉ đổi a[k] thành giá trị mới","Dịch các phần tử từ cuối về phía phải trước khi gán a[k]","Xóa phần tử cuối trước mọi lần chèn","Dịch từ đầu sang phải trước khi chèn"],"answer":2},{"text":"Xóa phần tử ở chỉ số k trong mảng liên tiếp thường cần thao tác nào?","options":["Đảo ngược cả mảng","Dịch các phần tử từ k+1 về bên trái","Chèn thêm một phần tử 0","Dịch toàn bộ phần tử sang phải"],"answer":2},{"text":"Insertion sort xây dựng mảng tăng dần bằng cách nào?","options":["Chia mảng thành hai nửa bằng pivot","Luôn chọn phần tử lớn nhất đưa về đầu","Chỉ đổi hai phần tử đầu tiên","Chèn từng phần tử vào đoạn đầu đã được sắp xếp"],"answer":4},{"text":"Độ phức tạp xấu nhất của insertion sort đối với n phần tử là?","options":["O(n)","O(log n)","O(1)","O(n²)"],"answer":4},{"text":"Khi insertion sort nhận mảng đã tăng dần, số lần dịch phần tử về cơ bản là?","options":["Luôn là n lần","n! lần","0 lần","n² lần"],"answer":3},{"text":"Mảng {5,2,4}, sau khi sắp xếp tăng dần sẽ là?","options":["{2,5,4}","{2,4,5}","{4,5,2}","{5,4,2}"],"answer":2},{"text":"Với mảng n phần tử, vị trí k hợp lệ để chèn thêm phần tử (đánh chỉ số từ 0) là?","options":["k < 0","0 < k < n","0 <= k <= n","k > n"],"answer":3},{"text":"Với mảng n phần tử, vị trí k hợp lệ để xóa phần tử là?","options":["k = n","0 <= k < n","0 <= k <= n","k < 0"],"answer":2},{"text":"Sau khi xóa một phần tử của mảng có 6 phần tử, số phần tử logic còn lại là?","options":["5","4","6","7"],"answer":1},{"text":"Khi chèn phần tử vào mảng tĩnh đã dùng hết dung lượng, cách xử lý đúng là?","options":["Báo không đủ chỗ hoặc sử dụng cấu trúc có thể mở rộng","Ghi vào a[n] bất kể kích thước khai báo","Giảm n rồi báo chèn thành công","Chèn đè phần tử bất kỳ mà không thông báo"],"answer":1}]},{"order":4,"questions":[{"text":"Với ma trận int a[3][4], số phần tử của ma trận là?","options":["12","7","3","4"],"answer":1},{"text":"Trong C++, a[i][j] của mảng hai chiều biểu thị điều gì?","options":["Phần tử hàng j, cột i trong mọi trường hợp","Toàn bộ hàng i","Toàn bộ cột j","Phần tử hàng i, cột j"],"answer":4},{"text":"Để tính tổng từng hàng ma trận m×n, cần duyệt như thế nào?","options":["Chỉ duyệt phần tử đường chéo","Chỉ cộng cột đầu tiên","Với mỗi hàng i, cộng các cột j từ 0 đến n-1","Chỉ duyệt hàng cuối"],"answer":3},{"text":"Ma trận vuông kích thước n×n có bao nhiêu phần tử trên đường chéo chính?","options":["n²","n","n-1","2n"],"answer":2},{"text":"Điều kiện để a[i][j] nằm trên đường chéo chính là?","options":["i + j == n","i > j","i == j","i == n"],"answer":3},{"text":"Trong ma trận vuông n×n, điều kiện để phần tử thuộc đường chéo phụ là?","options":["i == j","i + j == n - 1","i * j == n","i + j == n"],"answer":2},{"text":"Với ma trận vuông 3×3, khi cộng cả hai đường chéo, phần tử nào xuất hiện trên cả hai?","options":["Phần tử a[0][0]","Phần tử ở giữa a[1][1]","Phần tử a[0][1]","Phần tử a[2][0]"],"answer":2},{"text":"Một ma trận có 2 hàng và 3 cột có phải ma trận vuông không?","options":["Có, vì có 6 phần tử","Không, vì số hàng khác số cột","Có, vì có nhiều hơn một hàng","Không, vì mọi ma trận phải là 3×3"],"answer":2},{"text":"Muốn tìm max của ma trận không rỗng có phần tử âm, khởi tạo nào an toàn?","options":["maxValue = a[m][n]","maxValue = m*n","maxValue = a[0][0]","maxValue = 0 trong mọi trường hợp"],"answer":3},{"text":"Với ma trận {{1,2},{3,4}}, tổng cột thứ hai (chỉ số 1) là?","options":["3","6","7","4"],"answer":2}]},{"order":5,"questions":[{"text":"Trong std::string của C++, phương thức nào trả về độ dài chuỗi?","options":["length_of()","push()","clear_size()","size()"],"answer":4},{"text":"Để xóa khoảng trắng đầu/cuối chuỗi, thao tác nào thích hợp?","options":["Chuyển chuỗi thành số nguyên","Xóa mọi ký tự giữa hai từ","Chỉ xóa ký tự đầu dù đó là chữ cái","Tìm vị trí ký tự không phải khoảng trắng đầu/cuối rồi lấy phần tương ứng"],"answer":4},{"text":"Chuỗi \"  xin   chao  \" sau khi chuẩn hóa khoảng trắng thành một dấu cách là?","options":["\"xin   chao\"","\"  xin chao  \"","\"xinchao\"","\"xin chao\""],"answer":4},{"text":"std::getline(std::cin, s) thường dùng khi nào?","options":["Khi cần nhập cả dòng gồm nhiều từ","Khi chỉ nhập một ký tự số","Khi nhập riêng số nguyên bằng cin >>","Khi tự động chuyển chữ thành UTF-16"],"answer":1},{"text":"Trong chuỗi ASCII, std::isspace có thể được dùng để kiểm tra gì?","options":["Ký tự số nguyên tố","Độ dài của toàn bộ chuỗi","Ký tự khoảng trắng như space hoặc tab","Ký tự viết hoa duy nhất"],"answer":3},{"text":"Khi tách câu bằng std::istringstream ss(s); ss >> word, kết quả thông thường là?","options":["Mỗi ký tự thành một từ","Các từ phân cách bởi khoảng trắng","Chuỗi được sắp xếp theo chữ cái","Mọi dấu câu đều bị xóa tự động"],"answer":2},{"text":"Với chuỗi \"lap trinh\", có bao nhiêu từ phân cách bởi đúng một dấu cách?","options":["9","3","2","1"],"answer":3},{"text":"Để nối thêm từ vào cuối std::string s, lựa chọn nào đúng?","options":["s /= \"abc\";","s += \"abc\";","s -= \"abc\";","s *= \"abc\";"],"answer":2},{"text":"Khi xử lý tiếng Việt UTF-8 bằng std::string, nhận định nào đúng?","options":["size() đếm byte, không nhất thiết bằng số ký tự hiển thị","size() luôn đếm số chữ cái tiếng Việt","Truy cập s[i] luôn thu được một ký tự Unicode đầy đủ","Mỗi ký tự tiếng Việt luôn chiếm một byte"],"answer":1},{"text":"Với std::string s=\"abc\", biểu thức s.substr(1,2) cho kết quả nào?","options":["\"ab\"","\"bc\"","\"a\"","\"abc\""],"answer":2}]},{"order":6,"questions":[{"text":"std::string::find() trả về gì khi không tìm thấy chuỗi con?","options":["std::string::npos","Độ dài chuỗi cộng 1","-1 với kiểu int trong mọi trường hợp","0"],"answer":1},{"text":"Với s=\"banana\", s.find(\"na\") trả về chỉ số nào?","options":["1","4","2","3"],"answer":3},{"text":"Trong chuỗi \"aaaa\", chuỗi con \"aa\" xuất hiện bao nhiêu lần nếu cho phép chồng lấn?","options":["1","2","3","4"],"answer":3},{"text":"Muốn đếm lần xuất hiện chuỗi con có chồng lấn, sau khi tìm thấy tại pos nên bắt đầu tìm tiếp từ?","options":["pos + s.size()","pos + mẫu.size()","0 trong mọi lần tìm","pos + 1"],"answer":4},{"text":"Với s=\"abcabc\", thay tất cả \"ab\" bằng \"X\" (không chồng lấn) được?","options":["\"abcX\"","\"XXcc\"","\"Xabc\"","\"XcXc\""],"answer":4},{"text":"Tại sao cần từ chối mẫu tìm kiếm rỗng trong vòng lặp thay thế chuỗi con?","options":["Để tránh vòng lặp không tiến triển hoặc hành vi không mong muốn","Vì ký tự ASCII không thể thay thế","Vì std::string không chứa chuỗi rỗng","Vì chuỗi rỗng chỉ dùng được với int"],"answer":1},{"text":"std::string::replace(pos, len, replacement) có tác dụng gì?","options":["Tìm vị trí xuất hiện cuối","Đảo ngược chuỗi theo pos","Thay đoạn bắt đầu tại pos dài len ký tự bằng replacement","Xóa toàn bộ chuỗi và thay bằng len"],"answer":3},{"text":"Với s=\"abc\", s.find(\"xyz\") trả về giá trị nào?","options":["0","3","1","std::string::npos"],"answer":4},{"text":"Khi thay thế các lần xuất hiện không chồng lấn trên chuỗi gốc, cách nào dễ tránh đếm trùng?","options":["Duyệt chuỗi gốc và tăng vị trí theo độ dài mẫu sau mỗi lần khớp","Ghi trực tiếp lên chuỗi rồi không thay đổi vị trí","Luôn lùi vị trí về 0 sau mỗi lần khớp","Luôn bỏ qua một ký tự bất kể mẫu dài bao nhiêu"],"answer":1},{"text":"Khi s=\"aaaa\", thay mỗi \"aa\" không chồng lấn bằng \"b\", kết quả là?","options":["\"ab\"","\"ba\"","\"bb\"","\"bbb\""],"answer":3}]},{"order":7,"questions":[{"text":"Trong hàm đệ quy, trường hợp cơ sở dùng để làm gì?","options":["Cấp phát tất cả biến toàn cục","Tăng mãi số lần gọi hàm","Bắt buộc hàm phải trả về void","Kết thúc chuỗi lời gọi đệ quy tại điều kiện xác định"],"answer":4},{"text":"Giá trị 0! theo định nghĩa giai thừa là?","options":["1","0","Không xác định","-1"],"answer":1},{"text":"Hàm factorial(n)=n*factorial(n-1) với n>0 cần trường hợp cơ sở nào?","options":["factorial(-1)=1","factorial(0)=0","factorial(n)=n với mọi n","factorial(0)=1"],"answer":4},{"text":"Với F(0)=0, F(1)=1 và F(n)=F(n-1)+F(n-2), F(5) bằng?","options":["8","3","5","4"],"answer":3},{"text":"Đệ quy trực tiếp tính Fibonacci theo công thức hai nhánh có vấn đề hiệu năng chính nào?","options":["Tính lặp lại nhiều bài toán con","Không cần trường hợp cơ sở","Luôn chạy trong O(1)","Chỉ dùng được cho n=0"],"answer":1},{"text":"Cài đặt Fibonacci bằng vòng lặp với số bước tăng tuyến tính theo n thường có độ phức tạp?","options":["O(2ⁿ)","O(n²)","O(n)","O(log n)"],"answer":3},{"text":"Với đệ quy tuyến tính đơn giản chỉ gọi một lần trên n-1 mỗi bước, chiều sâu ngăn xếp thường là?","options":["O(log log n)","O(n²)","O(n)","O(1) trong mọi môi trường"],"answer":3},{"text":"Vì sao cần giới hạn n khi tính giai thừa bằng kiểu số nguyên cố định?","options":["n luôn nhỏ hơn 10","Kết quả có thể tràn miền biểu diễn","Đệ quy không thể trả về số nguyên","Giai thừa luôn là số âm"],"answer":2},{"text":"Khi người dùng nhập n âm cho hàm giai thừa trên số nguyên không âm, nên?","options":["Đổi mọi n âm thành 1 mà không thông báo","Trả về 0 rồi báo đúng theo định nghĩa","Tiếp tục gọi factorial(n-1) vô hạn","Từ chối đầu vào hoặc xử lý lỗi"],"answer":4},{"text":"Tính tổng từ 1 đến n bằng hàm S(n)=n+S(n-1), S(0)=0 thì S(4) là?","options":["4","6","16","10"],"answer":4}]},{"order":8,"questions":[{"text":"Đệ quy hỗ tương là trường hợp nào?","options":["Hai hoặc nhiều hàm gọi qua lại lẫn nhau","Một hàm không gọi hàm nào","Hai hàm hoàn toàn độc lập","Một hàm chỉ chạy trong vòng lặp for"],"answer":1},{"text":"Để hai hàm isEven/isOdd gọi lẫn nhau trong C++, điều thường cần là?","options":["Khai báo hàm trước để trình biên dịch biết tên","Định nghĩa cả hai bên trong main như hàm lồng","Đổi mọi tham số sang kiểu double","Bỏ mọi điều kiện dừng"],"answer":1},{"text":"Với isEven(0)=true và isEven(n)=isOdd(n-1), isOdd(0)=false, giá trị isEven(4) là?","options":["true","false","Không kết thúc","Chỉ xác định khi n lẻ"],"answer":1},{"text":"Đệ quy lồng M(M(n+11)) khác đệ quy đơn n-1 ở điểm nào?","options":["Không bao giờ cần trường hợp dừng","Không có tham số đầu vào","Luôn chỉ gọi hàm một lần","Một lời gọi đệ quy làm đối số cho lời gọi đệ quy khác"],"answer":4},{"text":"Theo định nghĩa McCarthy 91: M(n)=n-10 nếu n>100, ngược lại M(M(n+11)). M(101) bằng?","options":["100","91","90","101"],"answer":2},{"text":"Theo định nghĩa McCarthy 91, giá trị M(100) là?","options":["89","100","91","90"],"answer":3},{"text":"Trong đệ quy hỗ tương isEven/isOdd trên n không âm, mỗi lần gọi với n-1 sẽ giúp?","options":["Bỏ qua điều kiện cơ sở","Đưa bài toán dần về trường hợp cơ sở n=0","Tăng n mãi mãi","Làm số lần gọi luôn bằng 1"],"answer":2},{"text":"Khi cài đặt đệ quy lồng sâu, rủi ro kỹ thuật cần chú ý là?","options":["Không thể trả kết quả kiểu int","Tràn chỉ do chuỗi UTF-8","Lỗi chỉ vì thiếu iostream","Tràn ngăn xếp do số lời gọi quá sâu"],"answer":4},{"text":"Nếu gọi isEven(-1) nhưng chỉ có trường hợp cơ sở n==0 và luôn gọi n-1, điều gì có thể xảy ra?","options":["Trả về true chắc chắn","Hàm tự kết thúc ngay","Trả về false chắc chắn","Đệ quy không tiến về trường hợp cơ sở"],"answer":4},{"text":"Mô tả nào đúng về M(50) của hàm McCarthy 91?","options":["Kết quả bằng 101","Kết quả bằng 40","Kết quả bằng 50","Kết quả bằng 91"],"answer":4}]}]$quizdata$::jsonb;
  v_titles jsonb := $titles$["Phong cách lập trình, ngoại lệ và tập tin", "Mảng một chiều: tổng, đếm, tìm kiếm, min/max", "Sắp xếp, thêm và xóa phần tử", "Mảng hai chiều và ma trận", "Chuỗi cơ bản, chuẩn hóa và token", "Tìm kiếm, đếm và thay thế chuỗi con", "Đệ quy tuyến tính và nhị phân", "Đệ quy lồng, hỗ tương và ứng dụng"]$titles$::jsonb;
BEGIN
  SELECT course_id INTO v_course FROM lms.curated_courses WHERE course_key='programming-techniques';
  IF v_course IS NULL THEN RAISE EXCEPTION 'Course programming-techniques not found'; END IF;
  SELECT count(*) INTO v_count FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
    WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted;
  IF v_count<>8 THEN RAISE EXCEPTION 'Expected 8 published KTLT lessons, found %',v_count; END IF;

  -- Preflight ALL lessons. Protect teacher-authored published quizzes and existing histories.
  FOR r IN
    SELECT l.lesson_id,l.title,row_number() OVER (ORDER BY l.lesson_order,l.lesson_id) AS rn
    FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
    WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted
  LOOP
    IF trim(regexp_replace(r.title,'^[[:space:]]*[0-9]+[[:space:]]*[.·:-]*[[:space:]]*','')) <> (v_titles->>(r.rn::int-1)) THEN
      RAISE EXCEPTION 'KTLT lesson % title mismatch: %',r.rn,r.title;
    END IF;
    IF (SELECT count(*) FROM assessment.quizzes WHERE course_id=v_course AND lesson_id=r.lesson_id AND NOT is_deleted AND is_published
      AND coalesce(description,'') NOT LIKE '[VEDU-LESSON-QUIZ-V1]%'
      AND coalesce(description,'')<>v_tag)>0 THEN
      RAISE EXCEPTION 'Teacher or unknown quiz already published for KTLT lesson %; no change',r.rn;
    END IF;
    IF (SELECT count(*) FROM assessment.quizzes WHERE course_id=v_course AND lesson_id=r.lesson_id AND NOT is_deleted AND description=v_tag)>1 THEN
      RAISE EXCEPTION 'Duplicate KTLT V2 quizzes at lesson %',r.rn;
    END IF;
    item:=v_data->(r.rn::int-1);
    IF item IS NULL OR jsonb_array_length(item->'questions')<>10 THEN
      RAISE EXCEPTION 'KTLT lesson % lacks exactly 10 questions',r.rn;
    END IF;
  END LOOP;

  FOR r IN
    SELECT l.lesson_id,l.title,row_number() OVER (ORDER BY l.lesson_order,l.lesson_id) AS rn
    FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
    WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted
    ORDER BY l.lesson_order,l.lesson_id
  LOOP
    item:=v_data->(r.rn::int-1);
    SELECT quiz_id INTO v_qid FROM assessment.quizzes
      WHERE course_id=v_course AND lesson_id=r.lesson_id AND NOT is_deleted AND description=v_tag LIMIT 1;
    IF v_qid IS NULL THEN
      INSERT INTO assessment.quizzes(course_id,lesson_id,title,description,time_limit_seconds,passing_score,max_attempts,is_published)
      VALUES (v_course,r.lesson_id,'Quiz cuối bài — '||r.title,v_tag,900,7,3,false)
      RETURNING quiz_id INTO v_qid;
      v_question_order:=0;
      FOR q IN SELECT value FROM jsonb_array_elements(item->'questions') LOOP
        v_question_order:=v_question_order+1;
        INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
        VALUES(v_qid,q->>'text','SINGLE_CHOICE',v_question_order,1)
        RETURNING question_id INTO v_question;
        v_answer_order:=0;
        FOR v_answer IN SELECT value#>>'{}' FROM jsonb_array_elements(q->'options') LOOP
          v_answer_order:=v_answer_order+1;
          INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
          VALUES(v_question,v_answer,v_answer_order=(q->>'answer')::int,v_answer_order);
        END LOOP;
      END LOOP;
    END IF;
    SELECT count(*) INTO v_current_count FROM assessment.questions WHERE quiz_id=v_qid;
    IF v_current_count<>10 THEN RAISE EXCEPTION 'KTLT lesson % quiz has % questions, expected 10',r.rn,v_current_count; END IF;
    -- Do not delete old attempts or old generated quizzes; only deactivate previous generic quiz.
    UPDATE assessment.quizzes SET is_published=false,updated_at=now()
      WHERE course_id=v_course AND lesson_id=r.lesson_id AND NOT is_deleted AND is_published
        AND coalesce(description,'') LIKE '[VEDU-LESSON-QUIZ-V1]%';
    UPDATE assessment.quizzes SET is_published=true, updated_at=now()
      WHERE quiz_id=v_qid AND NOT is_published;
  END LOOP;
END $vedu_ktlt_23$;
COMMIT;
